do $$declare a uuid=(select id from bf where name='a');b uuid=(select id from bf where name='b');n int;k int;pid uuid;ids uuid[];person uuid;rid uuid;prod text;cost int;r jsonb;ms bigint=extract(epoch from now()-interval '2 days')*1000;begin
