 insert into kiyi_private.badge_map_days select a,'lara',(now()at time zone 'Europe/Istanbul')::date-off from generate_series(0,2)g(off);insert into kiyi_private.badge_map_days select a,'kultur',(now()at time zone 'Europe/Istanbul')::date-off from generate_series(0,4)g(off);perform kiyi_private.badge_sync(a);perform kiyi_private.badge_sync(a);assert(select count(*)from kiyi_private.badge_earned where owner=a and code like 'map_%'and active)=4;
