 assert(select balance from public.kiyi_wallets where user_id=a)=0;assert(select sum(x)from kiyi_private.reward_settings,unnest(daily)x)=320;assert(select referral_amount from kiyi_private.reward_settings)=75;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b)::text,true);r=public.kiyi_command('badge_dashboard',jsonb_build_object('owner',a,'progress',999999));assert not exists(select 1 from jsonb_array_elements(r->'items')i where(i->>'earned')::bool);assert(r->>'total')::int=jsonb_array_length(r->'items');
 assert not has_table_privilege('authenticated','kiyi_private.badge_earned','INSERT');assert not has_function_privilege('authenticated','kiyi_private.badge_sync(uuid)','EXECUTE');
